def fit2(mode,nf=8,split=None):
    SH,HT,B=feats(split,nf); K=nf+2
    def nll(th):
        a=th[0]; w=np.exp(log_softmax(np.r_[0,th[3:3+K-1]]))
        num=HT@w[:nf]+B@w[nf:]; den=SH@w[:nf]+w[nf:].sum(); mis=den-num
        if mode=='diff': z=a+np.exp(th[1])*num-np.exp(th[2])*mis
        if mode=='ratiopow': z=a+np.exp(th[1])*(num/den)*den**th[2]
        if mode=='ratio_plus_mass': z=a+np.exp(th[1])*(num/den)+th[2]*np.log(den)
        p=np.clip(expit(z),1e-9,1-1e-9)
        return -(y*np.log(p)+(1-y)*np.log(1-p)).sum()
    best=None
    for s in range(5):
        th0=np.r_[-2,1.5,0.,np.random.RandomState(s).randn(K-1)*.3]
        r=minimize(nll,th0,method='L-BFGS-B')
        if best is None or r.fun<best.fun: best=r
    w=np.exp(log_softmax(np.r_[0,best.x[3:]]))
    print(mode,round(best.fun,2),np.round(best.x[:3],2),np.round(w,3))
if __name__=='__main__':
    for m in sys.argv[1:]: fit2(m)
